const crypto = require('crypto');
const b = $json.body || $json;
if (!b.sanitized_message || !b.recipient || !b.channel) throw new Error('sanitized_message, recipient and channel are required');
const envelope = { sanitized_message: b.sanitized_message, recipient: b.recipient, channel: b.channel };
const message_sha256 = crypto.createHash('sha256').update(JSON.stringify(envelope)).digest('hex');
return [{ json: { request_id: b.request_id, approver: b.approver, ...envelope, message_sha256, sensitivity_flags: b.sensitivity_flags || [], removed_fields: b.removed_fields || [], callback_url: b.callback_url || 'https://YOUR-N8N/webhook/shsy-hr-message-result', timeout_minutes: b.timeout_minutes || 60 } }];

const crypto = require('crypto');
const c = $json.context || {};
const envelope = { sanitized_message: c.sanitized_final_message, recipient: c.recipient, channel: c.delivery_channel };
const freshHash = crypto.createHash('sha256').update(JSON.stringify(envelope)).digest('hex');
return [{ json: { ...$json, authorized: $json.status === 'approved' && freshHash === c.message_sha256, final_message: c.sanitized_final_message, recipient: c.recipient, delivery_channel: c.delivery_channel } }];
